let valueTarget=null,valueTimer=null;for(const output of document.querySelectorAll('output')){const label=output.closest('label'),slider=label?$(label.htmlFor):null;if(!slider||slider.type!=='range')continue;output.setAttribute('role','button');output.tabIndex=0;output.title='Нажмите: ввести значение. Двойное нажатие: сброс.';const open=()=>{if(slider.disabled||slider.closest('fieldset')?.disabled)return;valueTarget=slider;$('value-label').textContent=label.childNodes[0].textContent.trim();$('value-number').min=slider.min;$('value-number').max=slider.max;$('value-number').step=slider.step;$('value-number').value=slider.value;$('value-dialog').showModal();$('value-number').select();};output.onclick=()=>{clearTimeout(valueTimer);valueTimer=setTimeout(open,280);};output.ondblclick=()=>{clearTimeout(valueTimer);snapshot();slider.value=slider.id==='quality'?'95':slider.id==='strength'?'70':slider.id==='feather'?'25':slider.dataset.adjust?String(defaultEdit().adjust[slider.dataset.adjust]):'0';slider.dispatchEvent(new Event('input',{bubbles:true}));};output.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();open();}};slider.addEventListener('dblclick',()=>output.ondblclick());}$('value-form').onsubmit=e=>{e.preventDefault();const value=Number($('value-number').value);if(!valueTarget||!Number.isFinite(value)||value<Number(valueTarget.min)||value>Number(valueTarget.max))return;snapshot();valueTarget.value=value;valueTarget.dispatchEvent(new Event('input',{bubbles:true}));$('value-dialog').close();};$('value-reset').onclick=()=>{if(!valueTarget)return;$('value-number').value=valueTarget.id==='quality'?95:valueTarget.id==='strength'?70:valueTarget.id==='feather'?25:valueTarget.dataset.adjust?defaultEdit().adjust[valueTarget.dataset.adjust]:0;};$('value-cancel').onclick=()=>$('value-dialog').close();

$('mobile-auto').onclick=()=>$('autoedit').click();$('new-region').onclick=()=>{selectedRegion=-1;manual=true;showOriginal=false;regionList();paint();message('Проведите по фото, чтобы добавить область.');};for(const b of document.querySelectorAll('[data-mask-parameter-button]'))b.onclick=()=>{activeMaskParameter=b.dataset.maskParameterButton;syncMobileMaskParameter();};function syncMobileMaskParameter(){if((activeMaskParameter==='feather'&&$('effect').value!=='blur')||(activeMaskParameter==='strength'&&$('effect').value==='solid'))activeMaskParameter='effect';for(const row of document.querySelectorAll('[data-mask-parameter]'))row.dataset.active=row.dataset.maskParameter===activeMaskParameter;for(const b of document.querySelectorAll('[data-mask-parameter-button]')){b.setAttribute('aria-pressed',String(b.dataset.maskParameterButton===activeMaskParameter));b.disabled=b.dataset.maskParameterButton==='feather'&&$('effect').value!=='blur'||b.dataset.maskParameterButton==='strength'&&$('effect').value==='solid';}}syncMobileMaskParameter();
for(const slider of document.querySelectorAll('input[type=range]')){let touch=null;slider.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||!matchMedia('(max-width:800px)').matches)return;e.preventDefault();e.stopImmediatePropagation();touch={id:e.pointerId,x:e.clientX,y:e.clientY,value:Number(slider.value),started:false};slider.setPointerCapture(e.pointerId);},true);slider.addEventListener('pointermove',e=>{if(!touch||e.pointerId!==touch.id)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;if(!touch.started){if(Math.abs(dx)<9||Math.abs(dx)<Math.abs(dy)*1.3)return;touch.started=true;snapshot();}const min=Number(slider.min),max=Number(slider.max),step=Number(slider.step)||1,width=Math.max(1,slider.getBoundingClientRect().width),v=touch.value+dx/width*(max-min);slider.value=Math.max(min,Math.min(max,Math.round((v-min)/step)*step+min));slider.dispatchEvent(new Event('input',{bubbles:true}));});for(const event of ['pointerup','pointercancel','lostpointercapture'])slider.addEventListener(event,()=>{touch=null;});}

let wheelFrame=0,wheelAmount=0,wheelX=0,wheelY=0;const photoViewport=$('canvaswrap');photoViewport.title='Колесо — масштаб. Средняя кнопка мыши — перемещение.';photoViewport.addEventListener('wheel',e=>{if(!loaded||!matchMedia('(any-hover:hover) and (any-pointer:fine)').matches||!e.deltaY)return;e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?photoViewport.clientHeight:1);if(e.shiftKey){photoViewport.scrollLeft+=delta;return;}wheelAmount+=Math.max(-200,Math.min(200,delta));wheelX=e.clientX;wheelY=e.clientY;if(!wheelFrame)wheelFrame=requestAnimationFrame(()=>{wheelFrame=0;zoomAt(zoom*Math.exp(-wheelAmount*.0015),wheelX,wheelY);wheelAmount=0;});},{passive:false});let mousePan=null;photoViewport.addEventListener('pointerdown',e=>{if(!loaded||e.button!==1||e.pointerType==='touch')return;e.preventDefault();e.stopImmediatePropagation();mousePan={id:e.pointerId,x:e.clientX,y:e.clientY,left:photoViewport.scrollLeft,top:photoViewport.scrollTop};photoViewport.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';},true);photoViewport.addEventListener('pointermove',e=>{if(!mousePan||e.pointerId!==mousePan.id)return;e.preventDefault();e.stopPropagation();photoViewport.scrollLeft=mousePan.left+mousePan.x-e.clientX;photoViewport.scrollTop=mousePan.top+mousePan.y-e.clientY;},true);for(const event of ['pointerup','pointercancel'])photoViewport.addEventListener(event,e=>{if(mousePan&&e.pointerId===mousePan.id){mousePan=null;canvas.style.cursor='default';e.stopPropagation();}},true);document.addEventListener('keydown',e=>{if(!loaded||e.ctrlKey||e.metaKey||e.altKey||e.target.isContentEditable||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='0'){$('zoom-fit').click();e.preventDefault();}});
const icons={editor:'<path d="M4 7h7m4 0h5M4 17h3m4 0h9"/><circle cx="13" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>',crop:'<path d="M7 3v14h14M3 7h14v14"/>',hide:'<path d="M3 3l18 18M10.5 5.2C15 4.5 19 7 22 12a18 18 0 0 1-4 4M6.5 6.5A18 18 0 0 0 2 12c5 8 11 9 16 5"/><path d="M10 10a3 3 0 0 0 4 4"/>',text:'<path d="M5 6V4h14v2M12 4v16M8 20h8"/>',undo:'<path d="M8 5 3 10l5 5M3 10h11a6 6 0 0 1 6 6v3"/>',redo:'<path d="m16 5 5 5-5 5m5-5H10a6 6 0 0 0-6 6v3"/>',reset:'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',expand:'<path d="m8 7 4-4 4 4m-4-4v18m-4-4 4 4 4-4"/>'};function uiIcon(path){const span=document.createElement('span');span.className='ui-icon';span.setAttribute('aria-hidden','true');span.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">'+path+'</svg>';return span;}for(const button of document.querySelectorAll('[data-tool]'))button.querySelector('span').replaceChildren(uiIcon(icons[button.dataset.tool]));for(const [id,key]of [['undo','undo'],['redo','redo'],['resetphoto','reset'],['panel-toggle','expand']])$(id).replaceChildren(uiIcon(icons[key]));$('resetphoto').setAttribute('aria-label','Сбросить все изменения');$('resetphoto').title='Сбросить все изменения';$('open-export').querySelector('span').replaceChildren(uiIcon(icons.download));
